import{_ as e}from"./chunks/4.4-zpfiltr.CDulehK1.js";import{_ as a,o as n,c as t,aa as i}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/media/cs/news/4.4-cislo_stavby.png",r="/buildary-help-preview/media/cs/news/4.4-lokalizace_stavby.png",s="/buildary-help-preview/media/cs/news/4.4-import_ciselniku.png",v="/buildary-help-preview/media/cs/news/4.4-kompet_vykresy_ukol.png",p="/buildary-help-preview/media/cs/news/4.4-denik_koo_bozp.png",d="/buildary-help-preview/media/cs/news/4.4-nove_povoleni.png",k="/buildary-help-preview/media/cs/news/4.4-skryti_sekci.png",u="/buildary-help-preview/media/cs/news/4.4-kompet_obdobiaimport.png",c="/buildary-help-preview/media/cs/news/4.4-smlouvyvspp.png",y="/buildary-help-preview/media/cs/news/4.4-detailsmlouvy.png",h="/buildary-help-preview/media/cs/news/4.4-filtrsmlouvy.png",x=JSON.parse('{"title":"Novinky verze 4.4 ve zkratce","description":"","frontmatter":{"title":"Novinky verze 4.4 ve zkratce","wiki":"cs:news:vrsion_4.4"},"headers":[],"relativePath":"news/version_4-4.md","filePath":"news/version_4-4.md","lastUpdated":1793708206000}'),m={name:"news/version_4-4.md"};function b(z,o,f,w,g,_){return n(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="novinky-verze-4-4-ve-zkratce" tabindex="-1">Novinky verze 4.4 ve zkratce <a class="header-anchor" href="#novinky-verze-4-4-ve-zkratce" aria-label="Permalink to &quot;Novinky verze 4.4 ve zkratce&quot;">​</a></h1><p>Změn je mnoho a všechny vám zásadním způsobem usnadní práci. Věříme, že budete nadšeni.<br> Informace o novinkách se už od verze 4.0 dozvídáte přímo v aplikaci v Nastavení vašeho profilu (ikona panáčka vpravo nahoře v tmavé liště), a zároveň v Nápovědě k celé aplikaci (ikona otazníku vpravo nahoře v tmavé liště).</p><ul><li>Navýšení počtu znaků v poli Číslo stavby dle zhotovitele a Číslo stavby dle stavebníka</li><li>Navýšení počtu znaků při lokalizaci stavby v poli Místo stavby</li><li>Zakázání ukončení stavby bez podepsání všech vyplněných denních protokolů</li><li>Kontrola importu číselníků pro modul Stavební deník</li><li>Vytvoření nové kompetence v okruhu Stavba</li><li>Vytvoření nové kompetence v okruhu Managementu úkolů</li><li>Úprava typu deníku koordinátora BOZP</li><li>Doplnění dalších 2 typů stavebních povolení</li><li>Přidání funkce pro možnost skrytí konkrétních sekcí v denních záznamech</li><li>SPP období</li><li>Vytvoření nové uživatelské role Přípravář pro SPP</li><li>Přidání odběratelských a dodavatelských smluv z RSV do Buildary.Online</li><li>Úprava exportu v SPP</li></ul><h2 id="zmeny-v-urovni-nastaveni-stavby" tabindex="-1">Změny v úrovni Nastavení stavby <a class="header-anchor" href="#zmeny-v-urovni-nastaveni-stavby" aria-label="Permalink to &quot;Změny v úrovni Nastavení stavby&quot;">​</a></h2><h3 id="navyseni-poctu-znaku-v-poli-cislo-stavby-dle-zhotovitele-a-cislo-stavby-dle-stavebnika" tabindex="-1">Navýšení počtu znaků v poli Číslo stavby dle zhotovitele a Číslo stavby dle stavebníka <a class="header-anchor" href="#navyseni-poctu-znaku-v-poli-cislo-stavby-dle-zhotovitele-a-cislo-stavby-dle-stavebnika" aria-label="Permalink to &quot;Navýšení počtu znaků v poli Číslo stavby dle zhotovitele a Číslo stavby dle stavebníka&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+l+'" alt="" width="600" loading="lazy"><br></p></div><p>V Nastavení stavby byl navýšen maximální počet znaků pro pole Číslo stavby dle zhotovitele a Číslo stavby dle stavebníka z původních 24 na 40 znaků.</p><div class="clear"></div><h3 id="navyseni-poctu-znaku-pri-lokalizaci-stavby-v-poli-misto-stavby" tabindex="-1">Navýšení počtu znaků při lokalizaci stavby v poli Místo stavby <a class="header-anchor" href="#navyseni-poctu-znaku-pri-lokalizaci-stavby-v-poli-misto-stavby" aria-label="Permalink to &quot;Navýšení počtu znaků při lokalizaci stavby v poli Místo stavby&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+r+'" alt="" width="600" loading="lazy"><br></p></div><p>Při zadávání lokalizace stavby do mapy byl navýšen maximální počet znaků v poli Místo stavby na 128.</p><h3 id="zakazani-ukonceni-stavby-bez-podepsani-vsech-vyplnenych-dennich-protokolu" tabindex="-1">Zakázání ukončení stavby bez podepsání všech vyplněných denních protokolů <a class="header-anchor" href="#zakazani-ukonceni-stavby-bez-podepsani-vsech-vyplnenych-dennich-protokolu" aria-label="Permalink to &quot;Zakázání ukončení stavby bez podepsání všech vyplněných denních protokolů&quot;">​</a></h3><p>Týká se možného <u>nastavení domén v individuálním režimu</u> a vztahuje se na všechny stavební projekty v rámci jedné domény.</p><p>Aplikace provádí <strong>kontrolu podpisů všech denních protokolů</strong>. Pokud některý protokol není podepsán, proces ukončení stavby nebude povolen, dokud nebudou všechny protokoly řádně podepsány. Uživatel je informován zprávou „Nejsou podepsané všechny denní protokoly“.</p><h3 id="kontrola-importu-ciselniku-pro-modul-stavebni-denik" tabindex="-1">Kontrola importu číselníků pro modul Stavební deník <a class="header-anchor" href="#kontrola-importu-ciselniku-pro-modul-stavebni-denik" aria-label="Permalink to &quot;Kontrola importu číselníků pro modul Stavební deník&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+s+'" alt="" width="600" loading="lazy"><br></p></div><p>V Nastavení stavby v záložce Číselníky – stavební deník lze importovat číselníky prostřednictvím tlačítka Importovat Excel. Importované soubory musí splňovat pravidla uvedená při najetí na tlačítko (anglické pojmenování sloupců). <strong>Nově</strong> aplikace neumožní import souborů, které tato pravidla nesplňují, a zobrazí chybovou hlášku: „Záznamy nebyly naimportovány“.</p><h3 id="vytvoreni-novych-kompetenci-v-okruhu-stavba-a-management-ukolu" tabindex="-1">Vytvoření nových kompetencí v okruhu Stavba a Management úkolů <a class="header-anchor" href="#vytvoreni-novych-kompetenci-v-okruhu-stavba-a-management-ukolu" aria-label="Permalink to &quot;Vytvoření nových kompetencí v okruhu Stavba a Management úkolů&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+v+'" alt="" width="600" loading="lazy"><br></p></div><p><strong>V okruhu Stavba</strong> je nyní přidána kompetence, která se výhradně zaměřuje na <strong>správu částí stavby a výkresů</strong>, kde umožní uživateli přidávat a editovat části stavby, včetně přidávání, mazání částí stavby a práce s výkresy. U role <strong>Administrátor</strong> je tato kompetence povolena automaticky. Doposud byla tato kompetence součástí výběru „Administrace stavby“.</p><p><strong>V okruhu Management úkolů</strong> byla přidána kompetence <strong>Zadání nového úkolu</strong>, která umožní uživatelům omezit zadávání nových úkolů. Všechny role (kromě role Čtenář) mají defaultně tuto kompetenci povolenou a v případě potřeby je možné ji odebrat. V předchozí verzi mohli zadávat úkoly všichni uživatelé bez možnosti omezení.</p><h2 id="zmeny-v-modulu-stavebni-denik" tabindex="-1">Změny v modulu Stavební deník <a class="header-anchor" href="#zmeny-v-modulu-stavebni-denik" aria-label="Permalink to &quot;Změny v modulu Stavební deník&quot;">​</a></h2><h3 id="uprava-typu-deniku-koordinatora-bozp" tabindex="-1">Úprava typu deníku koordinátora BOZP <a class="header-anchor" href="#uprava-typu-deniku-koordinatora-bozp" aria-label="Permalink to &quot;Úprava typu deníku koordinátora BOZP&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+p+'" alt="" width="600" loading="lazy"><br></p></div><p>V předchozích verzích měl deník koordinátora BOZP stejnou podobu jako ostatní typy deníků a neobsahoval žádné specifické odlišnosti. V aktuální verzi byl tento deník upraven tak, aby lépe reflektoval specifické požadavky a potřeby koordinátorů BOZP a byl navržen v souladu s pravidly a standardy pro vedení tohoto typu dokumentace.</p><h3 id="doplneni-dalsich-2-typu-stavebnich-povoleni" tabindex="-1">Doplnění dalších 2 typů stavebních povolení <a class="header-anchor" href="#doplneni-dalsich-2-typu-stavebnich-povoleni" aria-label="Permalink to &quot;Doplnění dalších 2 typů stavebních povolení&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><img src="'+d+'" alt="" width="600" loading="lazy"></div><p>Do části <strong>Identifikační údaje</strong> stavby byly nově přidány dva typy stavebního povolení:<br><br></p><ol><li>Povolení (NStZ) Tento typ stavebního povolení označuje standardní povolení podle režimu nového stavebního zákona č. 283/2021 Sb. (NStZ). Jedná se o běžný proces, kdy stavebník žádá o povolení stavby a postupuje podle pravidel daných stavebním zákonem.<br><br></li><li>Povolení (Zrychlené řízení NStZ) Tento typ povolení umožňuje rychlejší proces schválení stavby v rámci nového stavebního zákona (NStZ). Obvykle se využívá u specifických druhů staveb, kde je zjednodušené řízení, například při stavbách s menším dopadem na okolí nebo při splnění určitých předem stanovených podmínek.</li></ol><h3 id="pridani-funkce-pro-moznost-skryti-konkretnich-sekci-v-dennich-zaznamech" tabindex="-1">Přidání funkce pro možnost skrytí konkrétních sekcí v denních záznamech <a class="header-anchor" href="#pridani-funkce-pro-moznost-skryti-konkretnich-sekci-v-dennich-zaznamech" aria-label="Permalink to &quot;Přidání funkce pro možnost skrytí konkrétních sekcí v denních záznamech&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+k+'" alt="" width="600" loading="lazy"><br></p></div><p>V Nastavení deníku byla přidána možnost <strong>zcela skrýt sekci</strong>, aby se v denních záznamech vůbec nezobrazovala. Pokud dojde ke skrytí sekce v průběhu stavby, všechny dosavadní záznamy zůstanou zachovány, pouze se přestanou zobrazovat. U nově generovaných PDF protokolů budou skryté.<br><br> Možnost skrytí je dostupná pro všechny sekce.</p><h2 id="zmeny-v-modulu-soupisy-provedenych-praci" tabindex="-1">Změny v modulu Soupisy provedených prací <a class="header-anchor" href="#zmeny-v-modulu-soupisy-provedenych-praci" aria-label="Permalink to &quot;Změny v modulu Soupisy provedených prací&quot;">​</a></h2><h3 id="zalozeni-obdobi" tabindex="-1">Založení období <a class="header-anchor" href="#zalozeni-obdobi" aria-label="Permalink to &quot;Založení období&quot;">​</a></h3><p>Při vytvoření nového období v soupisu provedených prací se datum „Od“ a „Do“ automaticky vyplní podle předchozího období. Pokud období začíná 1. dnem měsíce, konec bude nastaven na poslední den téhož měsíce. Pokud období začíná jiným, než 1. dnem měsíce, nastaví se konec na stejný den.</p><h3 id="vytvoreni-nove-uzivatelske-role-pripravar" tabindex="-1">Vytvoření nové uživatelské role Přípravář <a class="header-anchor" href="#vytvoreni-nove-uzivatelske-role-pripravar" aria-label="Permalink to &quot;Vytvoření nové uživatelské role Přípravář&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:400px;"><p><img src="'+u+'" alt="" width="400" loading="lazy"><br></p></div><p>Byla vytvořena nová uživatelská role pro modul Soupis provedených prací s názvem Přípravář. Tato role je navržena s následujícími kompetencemi:<br></p><ul><li><strong>Zakládání období</strong> – umožňuje vytvářet nová období v rámci projektu.</li><li><strong>Import rozpočtu</strong> – poskytuje oprávnění k importu rozpočtu v modulu SPP.</li></ul><p>Role Přípravář může být rozšířena o další specifické kompetence podle potřeby projektu.</p><h3 id="pridani-odberatelskych-a-dodavatelskych-smluv-z-rsv-do-buildary-online" tabindex="-1">Přidání odběratelských a dodavatelských smluv z RSV do Buildary.Online <a class="header-anchor" href="#pridani-odberatelskych-a-dodavatelskych-smluv-z-rsv-do-buildary-online" aria-label="Permalink to &quot;Přidání odběratelských a dodavatelských smluv z RSV do Buildary.Online&quot;">​</a></h3><img src="'+c+'" alt="" width="600" loading="lazy"> Při exportu rozpočtu z **RSV** (Řízení Stavební Výroby) **nebo KROS**u nově dochází k přenosu následujících informací: **Číslo smlouvy, Typ smlouvy a Předmět smlouvy**. **Číslo smlouvy** bylo přidáno do seznamu položek rozpočtu, zatímco **Typ smlouvy** a **Předmět smlouvy** byly zahrnuty do zobrazení detailu položky. Pokud je rozpočet importovaný z RSV nebo KROSu, tak je umožněno filtrovat i dle čísla smluv.<br><div class="wiki-float wiki-float-left" style="--w:600px;"><img src="'+y+'" alt="" width="600" loading="lazy"></div><img src="'+h+'" alt="" width="400" loading="lazy"><h3 id="uprava-exportu" tabindex="-1">Úprava exportu <a class="header-anchor" href="#uprava-exportu" aria-label="Permalink to &quot;Úprava exportu&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+e+'" alt="" width="600" loading="lazy"><br></p></div><p>Upravený export nyní zahrnuje <strong>pouze položky, které odpovídají aktuálně nastaveným filtrům</strong>. Pokud si uživatel vybere filtr např. na základě konkrétních čísel smluv, budou do exportu zahrnuty pouze ty položky, které odpovídají těmto zadaným kritériím.</p>',49)])])}const S=a(m,[["render",b]]);export{x as __pageData,S as default};
